WHERE NOT EXISTS (SELECT 1 FROM public.fact_verifications v WHERE v.entity_type='mcq' AND v.entity_id=(SELECT id FROM public.gk_mcqs WHERE canonical_hash='bfa4f34b1f752dc68c2fab8938f99c252c8110ec43eb8625d0b88c4f656f1c0f' LIMIT 1) AND v.claim_text='মিসর ও সিরিয়া কত সালে একত্রিত হয়ে ইউনাইটেড আরব রিপাবলিক গঠন করেছিল? — printed answer: ঘ');
INSERT INTO public.fact_verifications (source_page,entity_type,entity_id,claim_text,normalized_claim,verification_status,confidence,verification_sources,audit_note)
SELECT 623,'mcq',(SELECT id FROM public.gk_mcqs WHERE canonical_hash='12269817ff4dead8e9d38a077970641c831341b8df7d2cd0571eb693d0022b43' LIMIT 1),'মিসরে রাজতন্ত্রের অবসান ঘটে কবে? — printed answer: খ',NULL,'verified','high'::confidence_level,'["https://www.britannica.com/place/Egypt/The-revolution-and-the-Republic"]'::jsonb,'Direct corroboration and historical scope are documented in the batch verification ledger.'
WHERE NOT EXISTS (SELECT 1 FROM public.fact_verifications v WHERE v.entity_type='mcq' AND v.entity_id=(SELECT id FROM public.gk_mcqs WHERE canonical_hash='12269817ff4dead8e9d38a077970641c831341b8df7d2cd0571eb693d0022b43' LIMIT 1) AND v.claim_text='মিসরে রাজতন্ত্রের অবসান ঘটে কবে? — printed answer: খ');
INSERT INTO public.flashcards (subject_id,book_id,chapter_id,topic_id,front_text,back_text,source_type,source_id,source_key)
SELECT (SELECT id FROM public.subjects ORDER BY created_at ASC LIMIT 1),f.book_id,f.chapter_id,f.topic_id,f.title,f.fact_text,'fact',f.id,'batch0619-0623:fact:'||f.id::text FROM public.gk_facts f WHERE f.source_page BETWEEN 619 AND 623 AND NOT EXISTS (SELECT 1 FROM public.flashcards z WHERE z.source_key='batch0619-0623:fact:'||f.id::text);
INSERT INTO public.flashcards (subject_id,book_id,chapter_id,topic_id,front_text,back_text,source_type,source_id,source_key)
SELECT (SELECT id FROM public.subjects ORDER BY created_at ASC LIMIT 1),n.book_id,n.chapter_id,n.topic_id,n.title,n.content,'note',n.id,'batch0619-0623:note:'||n.id::text FROM public.gk_notes n WHERE n.source_page BETWEEN 619 AND 623 AND NOT EXISTS (SELECT 1 FROM public.flashcards z WHERE z.source_key='batch0619-0623:note:'||n.id::text);
INSERT INTO public.flashcards (subject_id,book_id,chapter_id,topic_id,front_text,back_text,source_type,source_id,source_key)
SELECT (SELECT id FROM public.subjects ORDER BY created_at ASC LIMIT 1),m.book_id,m.chapter_id,m.topic_id,m.question,'সঠিক উত্তর: '||o.option_key||'. '||o.option_text,'mcq',m.id,'batch0619-0623:mcq:'||m.id::text FROM public.gk_mcqs m JOIN public.gk_mcq_options o ON o.mcq_id=m.id AND o.is_correct WHERE m.source_page BETWEEN 619 AND 623 AND NOT EXISTS (SELECT 1 FROM public.flashcards z WHERE z.source_key='batch0619-0623:mcq:'||m.id::text);
INSERT INTO public.search_documents (entity_type,entity_id,title,body,english_metadata)
SELECT 'fact',f.id,f.title,f.fact_text,'Status-marked GK fact | source page '||f.source_page::text FROM public.gk_facts f WHERE f.source_page BETWEEN 619 AND 623 AND NOT EXISTS (SELECT 1 FROM public.search_documents d WHERE d.entity_type='fact' AND d.entity_id=f.id);
INSERT INTO public.search_documents (entity_type,entity_id,title,body,english_metadata)
SELECT 'note',n.id,n.title,n.content,'Structured source note | source page '||n.source_page::text FROM public.gk_notes n WHERE n.source_page BETWEEN 619 AND 623 AND NOT EXISTS (SELECT 1 FROM public.search_documents d WHERE d.entity_type='note' AND d.entity_id=n.id);
INSERT INTO public.search_documents (entity_type,entity_id,title,body,english_metadata)
SELECT 'mcq',m.id,NULL,m.question,'Past-exam MCQ | source page '||m.source_page::text||' | question '||m.source_question_number FROM public.gk_mcqs m WHERE m.source_page BETWEEN 619 AND 623 AND NOT EXISTS (SELECT 1 FROM public.search_documents d WHERE d.entity_type='mcq' AND d.entity_id=m.id);
COMMIT;